import type { SeedData } from './data.ts'

/**
 * Renders supabase/seed.sql: one call to reset_demo_data() with the seed as JSON, so
 * `npx supabase db reset` loads exactly the same data as `npm run seed` and the app's
 * "Reset demo data" button. Regenerate with `npm run seed -- --sql`; a test fails if stale.
 */
export function renderSeedSql(data: SeedData): string {
  const json = JSON.stringify(data, null, 2)
  if (json.includes('$seed$')) throw new Error('seed: data must not contain the $seed$ quote tag')
  return [
    '-- GENERATED by `npm run seed -- --sql` from src/lib/seed/data.ts — do not edit by hand.',
    '-- Loaded by `npx supabase db reset` after the migrations.',
    `select public.reset_demo_data($seed$${json}$seed$::jsonb);`,
    '',
  ].join('\n')
}
